import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type SalesDashboardProps = Record<string, any>;

// Helper to generate the graph path resembling the reference image
const generateGraphPaths = (width: number, height: number) => {
  // Rough percentage points [x%, y%] where y=0 is bottom, y=100 is top
  // Updated for a steady upward trend
  const rawData = [
    [0, 5], [4, 7], [8, 6], [12, 10], [16, 9], [20, 15], [24, 14],
    [28, 20], [32, 18], [36, 25], [40, 28], [44, 24], [48, 35],
    [52, 38], [56, 36], [60, 45], [64, 42], [68, 55], [72, 60],
    [76, 58], [80, 70], [84, 75], [88, 72], [92, 85], [96, 92], [100, 95]
  ];

  const mappedPoints = rawData.map(p => ({
    x: (p[0] / 100) * width,
    y: height - (p[1] / 100) * height,
  }));

  let pathD = `M ${mappedPoints[0].x} ${mappedPoints[0].y}`;
  for (let i = 1; i < mappedPoints.length; i++) {
    pathD += ` L ${mappedPoints[i].x} ${mappedPoints[i].y}`;
  }

  // Create a closed path for the gradient fill
  const fillD = `${pathD} L ${width} ${height} L 0 ${height} Z`;

  return { pathD, fillD };
};

const SalesDashboard: React.FC<SalesDashboardProps> = ({
  backgroundColor = "#e8e9e4", // Fallback, we use a gradient in render
  transparentBackground = false,
  durationInSeconds = 5,
  targetSalesNumber = 100000000,
  cardWidth = 1100,
  cardHeight = 700,
  finalPositionX = 38,
  finalPositionY = 35,
  cardBackgroundColor = "#ffffff",
  primaryTextColor = "#202124",
  secondaryTextColor = "#70757a",
  accentColor = "#1a73e8", // Google Blue
  trendColor = "#1e8e3e",  // Google Green
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // 1. Entrance Animation (Card sliding in from bottom right)
  const slideInSpring = spring({
    frame,
    fps,
    config: {
      damping: 14,
      mass: 1,
      stiffness: 100,
    },
  });

  // Calculate final position from properties
  const cardFinalLeft = width * (finalPositionX / 100);
  const cardFinalTop = height * (finalPositionY / 100);
  
  // Start fully off-screen to the bottom right
  const cardStartLeft = width;
  const cardStartTop = height;

  const cardLeft = interpolate(slideInSpring, [0, 1], [cardStartLeft, cardFinalLeft]);
  const cardTop = interpolate(slideInSpring, [0, 1], [cardStartTop, cardFinalTop]);
  const cardOpacity = interpolate(slideInSpring, [0, 0.5], [0, 1], { extrapolateRight: "clamp" });

  // 2. Number Counter Animation
  // Start counting after the card is mostly in (e.g., frame 15)
  const counterStartFrame = 15;
  const countDurationFrames = fps * 2.5; // Count over 2.5 seconds
  
  const countProgress = interpolate(
    frame - counterStartFrame,
    [0, countDurationFrames],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  // Ease out for the counter
  const easedCountProgress = 1 - Math.pow(1 - countProgress, 3);
  const currentSalesValue = Math.floor(interpolate(easedCountProgress, [0, 1], [0, targetSalesNumber]));
  
  const formattedSales = new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0,
  }).format(currentSalesValue);


  // Layout Constants for Card (Responsive to requested card dimensions)
  const graphWidth = Math.max(200, cardWidth - 200);
  const graphHeight = Math.max(100, cardHeight - 350);

  const { pathD, fillD } = generateGraphPaths(graphWidth, graphHeight);

  // Background style
  const bgStyle: React.CSSProperties = transparentBackground
    ? { backgroundColor: "transparent" }
    : { background: "radial-gradient(circle at center, #f0f0ed 0%, #d8dad3 100%)" };

  return (
    <AbsoluteFill style={{ ...bgStyle, fontFamily: interFamily, overflow: "hidden" }}>
      
      {/* Dashboard Card */}
      <div
        style={{
          position: "absolute",
          left: cardLeft,
          top: cardTop,
          width: cardWidth,
          height: cardHeight,
          backgroundColor: cardBackgroundColor,
          borderRadius: 16,
          boxShadow: "0 24px 64px rgba(0,0,0,0.12), 0 8px 24px rgba(0,0,0,0.08)",
          opacity: cardOpacity,
          padding: "48px 64px",
          display: "flex",
          flexDirection: "column",
          transition: "none",
        }}
      >
        {/* Top Stats Row */}
        <div style={{ display: "flex", flexDirection: "row", justifyContent: "space-between", alignItems: "flex-start", width: graphWidth, transition: "none" }}>
          
          {/* Main Stat: Total Sales */}
          <div style={{ display: "flex", flexDirection: "column", gap: 8, flex: 2, transition: "none" }}>
            <div style={{ color: secondaryTextColor, fontSize: 24, fontWeight: 500, letterSpacing: "-0.01em", transition: "none" }}>
              Total sales
            </div>
            <div style={{ color: primaryTextColor, fontSize: 64, fontWeight: 600, letterSpacing: "-0.03em", lineHeight: 1.1, transition: "none" }}>
              {formattedSales}
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 6, color: trendColor, fontSize: 20, fontWeight: 600, marginTop: 4, transition: "none" }}>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" style={{ transition: "none" }}>
                <path d="M7 17L17 7M17 7H7M17 7V17" />
              </svg>
              154.2K%
            </div>
          </div>

          {/* Secondary Stats */}
          <div style={{ display: "flex", flex: 1, gap: 48, justifyContent: "flex-end", transition: "none" }}>
            {/* Total Orders */}
            <div style={{ display: "flex", flexDirection: "column", gap: 8, transition: "none" }}>
              <div style={{ color: secondaryTextColor, fontSize: 18, fontWeight: 500, transition: "none" }}>
                Total orders
              </div>
              <div style={{ color: secondaryTextColor, fontSize: 28, fontWeight: 600, transition: "none" }}>
                1.47K
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 4, color: trendColor, fontSize: 16, fontWeight: 600, transition: "none" }}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" style={{ transition: "none" }}>
                  <path d="M7 17L17 7M17 7H7M17 7V17" />
                </svg>
                146.9K%
              </div>
            </div>

            {/* Conversion */}
            <div style={{ display: "flex", flexDirection: "column", gap: 8, transition: "none" }}>
              <div style={{ color: secondaryTextColor, fontSize: 18, fontWeight: 500, transition: "none" }}>
                Conversion
              </div>
              <div style={{ color: secondaryTextColor, fontSize: 28, fontWeight: 600, transition: "none" }}>
                1.47%
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 4, color: trendColor, fontSize: 16, fontWeight: 600, transition: "none" }}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" style={{ transition: "none" }}>
                  <path d="M7 17L17 7M17 7H7M17 7V17" />
                </svg>
                335%
              </div>
            </div>
          </div>
        </div>

        {/* Graph Section */}
        <div style={{ position: "relative", width: graphWidth, height: graphHeight, marginTop: 64, transition: "none" }}>
          
          {/* Y-Axis Labels & Grid Lines */}
          {[
            { label: "$10K", top: 0 },
            { label: "$5K", top: graphHeight / 2 },
            { label: "$0", top: graphHeight },
          ].map((tick, i) => (
            <React.Fragment key={i}>
              <div style={{
                position: "absolute",
                top: tick.top - 12, // center text on line
                left: -10,
                color: secondaryTextColor,
                fontSize: 18,
                fontWeight: 500,
                transition: "none"
              }}>
                {tick.label}
              </div>
              <div style={{
                position: "absolute",
                top: tick.top,
                left: 50,
                width: graphWidth - 50,
                height: 1,
                backgroundColor: i === 2 ? primaryTextColor : "#e8eaed", // Solid line for bottom, light for inner
                transition: "none"
              }} />
            </React.Fragment>
          ))}

          {/* X-Axis Labels */}
          <div style={{
            position: "absolute",
            bottom: -40,
            left: 50,
            width: graphWidth - 50,
            display: "flex",
            justifyContent: "space-between",
            color: secondaryTextColor,
            fontSize: 18,
            fontWeight: 500,
            transition: "none"
          }}>
            {["Feb 17", "Mar 8", "Mar 28", "Apr 17", "May 7"].map((label, i) => (
              <div key={i} style={{ transition: "none" }}>{label}</div>
            ))}
          </div>

          {/* The SVG Line Graph */}
          <svg 
            width={graphWidth - 50} 
            height={graphHeight} 
            style={{ position: "absolute", left: 50, top: 0, overflow: "visible", transition: "none" }}
          >
            <defs>
              <linearGradient id="fillGradient" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={accentColor} stopOpacity={0.15} />
                <stop offset="100%" stopColor={accentColor} stopOpacity={0.0} />
              </linearGradient>
            </defs>
            
            {/* Shaded Area underneath */}
            <path 
              d={fillD} 
              fill="url(#fillGradient)" 
              style={{ transition: "none" }}
            />
            
            {/* The Line */}
            <path 
              d={pathD} 
              fill="none" 
              stroke={accentColor} 
              strokeWidth="4" 
              strokeLinejoin="round"
              strokeLinecap="round"
              style={{ transition: "none" }}
            />
          </svg>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default SalesDashboard;